/// Simulates one transformer layer forward pass.
/// `bufs` is pre-allocated outside the hot path to avoid allocator overhead.
#[allow(clippy::too_many_arguments)]
fn layer_forward(
    x: &mut [f32],
    h: usize,
    inter: usize,
    attn_q_w: &[f32],
    attn_k_w: &[f32],
    attn_v_w: &[f32],
    attn_o_w: &[f32],
    ffn_gate_w: &[f32],
    ffn_up_w: &[f32],
    ffn_down_w: &[f32],
    scratch: &mut [f32],
    bufs: &mut LayerBuffers,
) {
    let LayerBuffers {
        q,
        k,
        v,
        attn_out,
        qk,
        qk_out,
        gate,
        up,
        ffn_out,
    } = bufs;

    q.fill(0.0);
    k.fill(0.0);
    v.fill(0.0);
    attn_out.fill(0.0);
    qk.fill(0.0);
    qk_out.fill(0.0);
    gate.fill(0.0);
    up.fill(0.0);
    ffn_out.fill(0.0);

    // --- Attention ---
    gemv(h, h, attn_q_w, x, q);
    gemv(h, h, attn_k_w, x, k);
    gemv(h, h, attn_v_w, x, v);

    // Simplified attention: Q @ K^T @ V (single head for bench)
    let head_dim = h;
    let scale = 1.0 / (head_dim as f32).sqrt();
    for i in 0..h {
        qk[0] += q[i] * k[i] * scale;
    }
    softmax(qk, qk_out);
    for i in 0..h {
        attn_out[i] = v[i] * qk_out[0];
    }

    gemv(h, h, attn_o_w, attn_out, scratch);
    for i in 0..h {
        x[i] += scratch[i];
    }

    // --- FFN ---
    gemv(inter, h, ffn_gate_w, x, gate);
    gemv(inter, h, ffn_up_w, x, up);
    swiglu(gate, up);
    gemv(h, inter, ffn_down_w, gate, ffn_out);

    for i in 0..h {
        x[i] += ffn_out[i];
    }
}

