//! Backend selection and platform-aware fallback logic.

use crate::tensor::DType;

/// Supported compute backends.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Backend {
    Cpu,
    Metal,
    Cuda,
    Mlx,
    Vulkan,
    /// Intel Arc GPUs via the Vulkan compute path.
    IntelArc,
}

impl std::str::FromStr for Backend {
    type Err = ();

    fn from_str(name: &str) -> Result<Self, Self::Err> {
        match name {
            "cpu" => Ok(Backend::Cpu),
            "metal" => Ok(Backend::Metal),
            "cuda" => Ok(Backend::Cuda),
            "mlx" => Ok(Backend::Mlx),
            "vulkan" => Ok(Backend::Vulkan),
            "intel-arc" | "arc" => Ok(Backend::IntelArc),
            _ => Err(()),
        }
    }
}

impl Backend {
    /// Return the canonical name of this backend.
    pub fn as_str(&self) -> &'static str {
        match self {
            Backend::Cpu => "cpu",
            Backend::Metal => "metal",
            Backend::Cuda => "cuda",
            Backend::Mlx => "mlx",
            Backend::Vulkan => "vulkan",
            Backend::IntelArc => "intel-arc",
        }
    }

    /// Determine the effective backend for the current platform.
    ///
    /// On non-macOS platforms, `Mlx` is downgraded to `Cpu` and a warning
    /// message is returned.
    pub fn effective(self) -> (Self, Option<&'static str>) {
        match self {
            Backend::Mlx if !cfg!(target_os = "macos") => (
                Backend::Cpu,
                Some("MLX backend requested but unavailable on Linux; falling back to CPU"),
            ),
            Backend::Vulkan => (Backend::Vulkan, None),
            Backend::IntelArc if cfg!(vulkan_available) => (Backend::IntelArc, None),
            Backend::IntelArc => (
                Backend::Vulkan,
                Some(
                    "Intel Arc backend requested but Vulkan was not detected at build time; using Vulkan fallback path",
