    let len = a.len();
    let mut sum = _mm256_setzero_ps();

    let chunks = len / 8;
    for i in 0..chunks {
        let va = unsafe { _mm256_loadu_ps(a.as_ptr().add(i * 8)) };
        let vb = unsafe { _mm256_loadu_ps(b.as_ptr().add(i * 8)) };
