/// causal backbone layers (e.g. 32 for a 32-layer model), so the MTP block is
/// appended immediately after the main stack.
fn rewrite_flat_mtp_tensor_names(
    tensors: &mut [(String, Dtype, Vec<usize>, Vec<u8>)],
    base_layer: usize,
) {
