pub fn json_schema_to_simple_grammar(schema: &serde_json::Value) -> String {
    if schema.get("type").and_then(|v| v.as_str()) == Some("object") {
        "root ::= \"{\" .* \"}\"".to_string()
    } else if schema.get("type").and_then(|v| v.as_str()) == Some("array") {
        "root ::= \"[\" .* \"]\"".to_string()
    } else {
        "root ::= .*".to_string()
    }
}

